// 2. Wallet Freeze
export async function freezeWallet(targetUserId: string, reason: string) {
  const { userId } = await requireAdminRole(['admin', 'super_admin']);
  const adminClient = supabaseAdmin();

  const { error } = await adminClient.rpc('admin_process_wallet_freeze', {
    p_user_id: targetUserId,
    p_freeze: true,
    p_reason: reason,
    p_admin_id: userId
  });

  if (error) {
    throw new Error(`Failed to freeze wallet: ${error.message}`);
  }

  return { success: true };
}

export async function unfreezeWallet(targetUserId: string, reason: string) {
  const { userId } = await requireAdminRole(['admin', 'super_admin']);
  const adminClient = supabaseAdmin();

  const { error } = await adminClient.rpc('admin_process_wallet_freeze', {
    p_user_id: targetUserId,
    p_freeze: false,
    p_reason: reason,
    p_admin_id: userId
  });

  if (error) {
    throw new Error(`Failed to unfreeze wallet: ${error.message}`);
  }

  return { success: true };
}

// 3. Soft Delete User (Administrative action closely tied to finance/bans)
export async function softDeleteUser(targetUserId: string, reason: string) {
  const { userId } = await requireAdminRole(['admin', 'super_admin']);
  const adminClient = supabaseAdmin();

  // Example soft delete: set status to 'deleted' and freeze wallet
  const { error: profileError } = await adminClient
    .from('profiles')
    .update({ status: 'deleted', is_wallet_frozen: true })
    .eq('id', targetUserId);

  if (profileError) throw new Error(`Soft delete failed: ${profileError.message}`);

  await logAuditEvent({
    action: 'admin.users.soft_delete',
    actor_user_id: userId,
    related_entity_id: targetUserId,
    related_entity_type: 'profile',
    meta: { reason }
  });

  return { success: true };
}

// 4. Export CSV
export async function exportTransactionsCSV(filters: TransactionFilters) {
  const { userId } = await requireAdminRole(['admin', 'super_admin']);
  enforceRateLimit('export_csv', userId, 2, 60000); // Max 2 exports per minute

  const adminClient = supabaseAdmin();
  
  // A naive fetch for MVP. Should rate limit in productions.
  let query = adminClient
    .from('vw_admin_journal_ledger')
    .select('*')
    .order('created_at', { ascending: false })
    .limit(1000); // hard limit to prevent OOM
    
  if (filters.event_type) query = query.eq('event_type', filters.event_type);
  if (filters.status) query = query.eq('status', filters.status);
  
  const { data, error } = await query;
  if (error) throw new Error('Query failed');
  
  await logAuditEvent({
    action: 'admin.finance.tx_export_csv',
    actor_user_id: userId,
    meta: { filters: filters as any, row_count: data?.length || 0 }
  });

  // Transform data to simple CSV string format or Base64
  // We'll return the JSON for the component to parse using papaparse or similar.
  return data;
}
